cy.get('.card-body').then($cards => {
  const portfoliosConValorCero = [];
  $cards.each((index, card) => {
    const $card = Cypress.$(card);
    const nombre = $card.find('h6.card-title span[data-toggle="tooltip"]').attr('data-original-title')?.trim();
    const rawValor = $card.find('h5.card-title span[data-toggle="tooltip"]').attr('data-original-title')?.trim();
    if (nombre && rawValor) {
      const valor = parseFloat(rawValor.replace(/\./g, '').replace(',', '.'));
      if (valor === 0) {
        portfoliosConValorCero.push(nombre);
      }
    }
  });
  cy.then(() => {
    if (portfoliosConValorCero.length > 0) {
      const lista = portfoliosConValorCero.join(', ');
      throw new Error(`❌ Los siguientes portfolios tienen valor cero: ${lista}.`);
    } else {
      cy.log('✅ Todos los portfolios tienen valor distinto de cero');
    }
  });
});

